class nginx {
  package { 'nginx': ensure => installed }
  file { '/etc/nginx/nginx.conf':
    content => template('nginx/nginx.conf.erb'),
    notify  => Service['nginx'],
  }
  service { 'nginx': ensure => running, enable => true }
}

build {
  sources = ["source.amazon-ebs.base"]
  provisioner "shell" { inline = ["curl -L https://omnitruck.chef.io/install.sh | sudo bash"] }
  provisioner "file"  { source = "cookbooks/", destination = "/tmp/cookbooks" }
  provisioner "shell" { inline = ["sudo chef-client --local-mode -o 'role[web]'"] }
}
